package api

import (
	"encoding/json"
	"log/slog"
	"net"
	"net/http"
	"sync"
	"time"
	"unicode/utf8"
)

// The beacon's bounded knobs (tv-playback-unblock D7). beaconBurst is the
// per-client allowance per beaconWindow ("tens per minute" per design); a
// client over it answers 429 rate_limited with NO log line — a looping TV
// must not flood the log. beaconDetailLimit bounds the free-text `detail`
// that reaches the log (log-forgery surface stays a bounded-length line).
const (
	beaconBurst       = 30
	beaconWindow      = time.Minute
	beaconDetailLimit = 256
	// beaconMaxKeys caps the limiter's key set: past it, expired windows are
	// pruned on the next Allow so the in-process map cannot grow without
	// bound under spoofed-source traffic.
	beaconMaxKeys = 1024
)

// beaconRequest is the body of POST /playback-events (D7 Interfaces — the
// single home of the wire shape; task 4.1's sender and 5.1's joint test post
// EXACTLY this). All five fields are required non-empty strings; `mode` is
// one of direct|hls, `phase` one of fatal|video-error|stalled. There is
// deliberately NO credential field in the shape (INV4: nothing token-shaped
// can enter, so nothing token-shaped can be logged or stored). item_id is
// accepted verbatim — the beacon never reads the store.
type beaconRequest struct {
	ItemID string `json:"item_id"`
	Mode   string `json:"mode"`
	Phase  string `json:"phase"`
	Code   string `json:"code"`
	Detail string `json:"detail"`
}

// beaconModes / beaconPhases are the closed vocabularies the shape
// validation enforces; anything else is a 400 bad_request.
var (
	beaconModes  = map[string]bool{"direct": true, "hls": true}
	beaconPhases = map[string]bool{"fatal": true, "video-error": true, "stalled": true}
)

// beaconLimiter is the per-client, in-process fixed-window counter behind
// the beacon's 429. It is plain local state on the app (never a Deps
// closure — there is no domain behind it, INV1 pure delegation) and it is
// deliberately NOT store-backed: the limit exists to bound log volume, so
// process restart resets it and that is fine. The client key is the remote
// IP: the resolved Principal carries only the Role (all TVs share
// RoleClient), and re-parsing the bearer credential in the handler would
// duplicate the middleware's authN — per-IP bounds the flood the design
// cares about (NAT-sharing a bucket is accepted: this is a log guard, not
// accounting).
type beaconLimiter struct {
	mu   sync.Mutex
	hits map[string]*beaconCounter
}

// beaconCounter is one client's fixed window: hits within
// [start, start+beaconWindow).
type beaconCounter struct {
	start time.Time
	n     int
}

// newBeaconLimiter builds the limiter over the package constants.
func newBeaconLimiter() *beaconLimiter {
	return &beaconLimiter{hits: map[string]*beaconCounter{}}
}

// allow records one hit for key and reports whether the client is still
// within its beaconBurst budget. Expired windows are reset in place; the
// key set is pruned only when it has grown past beaconMaxKeys (amortized
// O(1)).
func (l *beaconLimiter) allow(key string) bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := time.Now()
	if len(l.hits) > beaconMaxKeys {
		for k, w := range l.hits {
			if now.Sub(w.start) >= beaconWindow {
				delete(l.hits, k)
			}
		}
	}
	w := l.hits[key]
	if w == nil || now.Sub(w.start) >= beaconWindow {
		w = &beaconCounter{start: now}
		l.hits[key] = w
	}
	w.n++
	return w.n <= beaconBurst
}

// playbackEvent: the playback-event beacon (D7 — a route, not a subsystem).
// Validate shape (400 BEFORE the limiter: a malformed probe is answered
// harmlessly — it logs nothing and never consumes budget) → consume one
// rate-limit hit (429 rate_limited, no log line) → emit the ONE INFO line
// that is the beacon's entire effect → 204 no body. No store read anywhere:
// an unknown item_id is accepted verbatim, and the handler runs with a nil
// Deps.Store without complaint.
//
// @Summary      Record a playback-event beacon (fire-and-forget telemetry)
// @Tags         playback
// @ID           playback-event-beacon
// @Router       /playback-events [post]
// @Param        request body beaconRequest true "beacon payload"
// @Success      204 "beacon accepted; entire effect is one INFO log line"
// @Failure      400 {object} errorBody
// @Failure      429 {object} errorBody
func (a *app) playbackEvent(w http.ResponseWriter, r *http.Request) {
	var req beaconRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", "malformed JSON body", false)
		return
	}
	if req.ItemID == "" || req.Mode == "" || req.Phase == "" || req.Code == "" || req.Detail == "" {
		writeError(w, http.StatusBadRequest, "bad_request", "item_id, mode, phase, code and detail are all required", false)
		return
	}
	if !beaconModes[req.Mode] || !beaconPhases[req.Phase] {
		writeError(w, http.StatusBadRequest, "bad_request", "mode must be direct|hls and phase fatal|video-error|stalled", false)
		return
	}
	if !a.beacons.allow(clientKey(r)) {
		writeError(w, http.StatusTooManyRequests, "rate_limited", "too many playback events; slow down", false)
		return
	}
	// The beacon's entire effect (D7): one INFO line. Exactly the five
	// validated fields plus the UA — never a token, never a play URL (INV4),
	// detail truncated to beaconDetailLimit.
	slog.Info("playback event",
		"item", req.ItemID,
		"mode", req.Mode,
		"phase", req.Phase,
		"code", req.Code,
		"detail", truncateBeaconDetail(req.Detail),
		"ua", r.UserAgent(),
	)
	w.WriteHeader(http.StatusNoContent)
}

// clientKey extracts the per-client rate-limit key: the remote IP (host of
// host:port / [host]:port).
func clientKey(r *http.Request) string {
	host, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		return r.RemoteAddr
	}
	return host
}

// truncateBeaconDetail bounds `detail` to beaconDetailLimit bytes, backing
// off whole runes so the logged line stays valid UTF-8.
func truncateBeaconDetail(detail string) string {
	if len(detail) <= beaconDetailLimit {
		return detail
	}
	cut := detail[:beaconDetailLimit]
	for len(cut) > 0 && !utf8.ValidString(cut) {
		cut = cut[:len(cut)-1]
	}
	return cut
}
